//! Additional SID string and LUID-array helpers.
use super::{Luid,UnicodeString};
const SUCCESS:i32=0;const INVALID:i32=0xC000000Du32 as i32;const SMALL:i32=0xC0000023u32 as i32;
#[repr(C)] pub struct LuidAndAttributes{pub luid:Luid,pub attributes:u32}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_copy_luid_and_attributes_array(count:u32,src:*const LuidAndAttributes,dst:*mut LuidAndAttributes){if count==0||src.is_null()||dst.is_null(){return;}unsafe{core::ptr::copy(src,dst,count as usize);}}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_convert_sid_to_unicode_string(dst:*mut UnicodeString,sid:*const super::sid::SidHeader,allocate:u8)->i32{if dst.is_null()||sid.is_null()||allocate!=0{return INVALID;}let n=unsafe{super::sid::rtl_length_sid(sid)};if n==0{return INVALID;}let s=unsafe{&*sid};let auth=s.identifier_authority.value;let mut authority=0u64;for b in auth{authority=(authority<<8)|b as u64;}let count=s.sub_authority_count as usize;let mut tmp=[0u16;192];let mut p=0usize;for c in [b'S' as u16,b'-' as u16,b'1' as u16,b'-' as u16]{tmp[p]=c;p+=1;}fn pushnum(out:&mut [u16],p:&mut usize,mut v:u64){let mut t=[0u16;20];let mut n=0;loop{t[n]=(b'0'+(v%10) as u8) as u16;n+=1;v/=10;if v==0{break;}}for i in (0..n).rev(){out[*p]=t[i];*p+=1;}}pushnum(&mut tmp,&mut p,authority);for i in 0..count{tmp[p]=45;p+=1;let v=unsafe{*((sid as *const u8).add(8+i*4) as *const u32)};pushnum(&mut tmp,&mut p,v as u64);}let d=unsafe{&mut *dst};let bytes=p*2;if d.buffer.is_null()||d.maximum_length as usize<bytes{return SMALL;}unsafe{core::ptr::copy_nonoverlapping(tmp.as_ptr(),d.buffer,p);}d.length=bytes as u16;SUCCESS}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_equal_wnf_change_stamps(a:u32,b:u32)->u8{(a==b) as u8}
